<?php
function ac_field_options(string $field): ?array { $o=ac_options(); return match($field){ 'status'=>$o['status'], 'priority'=>$o['priority'], 'owner_or_responsible_role'=>$o['roles'], 'rights_status'=>$o['rights'], 'safety_status'=>$o['safety'], 'public_private_flag'=>$o['public'], default=>null }; }
function ac_record_form(array $r, bool $isNew=false): void { echo '<form class="record-form" method="post" enctype="multipart/form-data"><fieldset><legend>'.($isNew?'Create owner-managed record':'Edit owner-managed overlay').'</legend><input type="hidden" name="action" value="save_record"><input type="hidden" name="original_record_id" value="'.ac_e($isNew?'':$r['record_id']).'">'; foreach(ac_schema() as $f){ $v=$r[$f] ?? ''; echo '<label>'.ac_e($f); $opts=ac_field_options($f); if($opts){ echo '<select name="'.ac_e($f).'">'; foreach($opts as $opt){ $sel=(string)$opt===(string)$v?' selected':''; echo '<option'.$sel.'>'.ac_e($opt).'</option>'; } echo '</select>'; } elseif(in_array($f,['description','notes','linked_files','linked_records'],true)) echo '<textarea name="'.ac_e($f).'">'.ac_e(ac_text($v)).'</textarea>'; else echo '<input name="'.ac_e($f).'" value="'.ac_e(ac_text($v)).'">'; echo '</label>'; } echo '<button>Save record</button></fieldset></form>'; if(!$isNew){ echo '<form class="inline-form" method="post"><input type="hidden" name="action" value="delete_record"><input type="hidden" name="record_id" value="'.ac_e($r['record_id']).'"><button class="danger" onclick="return confirm(\'Archive/delete this owner record overlay?\')">Archive / delete</button></form>'; echo '<form class="record-form" method="post" enctype="multipart/form-data"><fieldset><legend>Upload and link file</legend><input type="hidden" name="action" value="upload_record_file"><input type="hidden" name="record_id" value="'.ac_e($r['record_id']).'"><input type="file" name="record_file" required><button>Upload file</button></fieldset></form>'; } }
function ac_blank_record(): array { return ac_complete_record(['record_id'=>'OWNER-'.date('Ymd-His'),'title'=>'','section'=>'owner','category'=>'owner-managed','timeline_moment_id_or_gen'=>'GEN','status'=>'draft','priority'=>'medium','owner_or_responsible_role'=>'owner','public_private_flag'=>'internal-only','rights_status'=>'needs review','safety_status'=>'needs review','description'=>'','notes'=>'','linked_files'=>[],'linked_records'=>[],'last_updated'=>date('Y-m-d')]); }
function ac_fixture_image_form(array $r): void { echo '<form class="inline-upload" method="post" enctype="multipart/form-data"><input type="hidden" name="action" value="upload_fixture_image"><input type="hidden" name="record_id" value="'.ac_e($r['record_id']).'"><input type="file" name="fixture_image" accept="image/*" required><button>Upload fixture image</button></form>'; }
